# Evaluate fixture check in headless chromium via playwright
node - <<'NODE'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
  await page.goto('file://' + process.cwd() + '/web/usability/match-limit-detailed-green-path.html');
  const check = await page.textContent('#check');
  const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
  console.log({ check, scrollWidth });
  await browser.close();
  if (!check.includes('ok=true')) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });
NODE
